// Define an attachment
public static final AttachmentType<MyData> MY_DATA = AttachmentType.builder(() -> new MyData())
    .serialize(MyData.CODEC)
    .build();

// Register
@SubscribeEvent
public static void registerAttachments(RegisterAttachmentsEvent event) {
    event.registerEntity(Entity.class, MY_DATA);
}

// Usage
MyData data = player.getData(MY_DATA);
data.setValue(42);
